import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BDvxthnG.js";const n="/aibutler/docs-versions/v1.1.2/img/en/persona-quick-create.png",m=JSON.parse('{"title":"Persona","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/persona.md","filePath":"en/guide/persona.md"}'),s={name:"en/guide/persona.md"};function i(h,e,l,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="persona" tabindex="-1">Persona <a class="header-anchor" href="#persona" aria-label="Permalink to &quot;Persona&quot;">​</a></h1><p>A persona is your AI assistant. Each one has its own name, avatar, memory, and model, and they don&#39;t interfere with each other. You can create several: one to handle work, one to help your kid study, one to keep an eye on your investments.</p><h2 id="create-a-new-persona" tabindex="-1">Create a new persona <a class="header-anchor" href="#create-a-new-persona" aria-label="Permalink to &quot;Create a new persona&quot;">​</a></h2><p>Click <strong>Personas ▾</strong> at the top of the main window → <strong>+ New persona…</strong>.</p><p><strong>The quickest way is one sentence</strong>: in <strong>One-line persona</strong> at the top of the page, write what it&#39;s for — for example &quot;a cook who teaches me simple home dishes&quot; — and click <strong>Ask the butler to build it</strong>. The butler picks a name, avatar and role, creates the persona, and tells you what it decided.</p><p><img src="'+n+'" alt="One-line persona at the top of the new-persona page"></p><p>To set things up yourself, use the form below: fill in a name and click <strong>Create and open</strong>.</p><p>Under <strong>Advanced</strong> you can also set:</p><ul><li><strong>Folder</strong>: where the persona&#39;s data is stored. This can&#39;t be changed once it&#39;s created — if you want it on a different drive, pick it here before creating.</li><li><strong>Wake-up line</strong>: the first thing it says each time you open it.</li><li><strong>Make butler</strong>: the butler is the hub for all personas — it can help you open or create other personas. There can only be one, globally.</li></ul><h2 id="edit-a-persona" tabindex="-1">Edit a persona <a class="header-anchor" href="#edit-a-persona" aria-label="Permalink to &quot;Edit a persona&quot;">​</a></h2><p><strong>Personas ▾</strong> → <strong>⚙ Manage personas…</strong>, then click <strong>Edit</strong> on a persona&#39;s card. The edit page has five tabs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>What it covers</th></tr></thead><tbody><tr><td>Basics</td><td>Name, avatar</td></tr><tr><td>AI</td><td>Access, engine, model — see <a href="/aibutler/docs-versions/v1.1.2/en/guide/models.html">Connecting Models</a></td></tr><tr><td>Profile</td><td>Who it is, how it talks, its rules</td></tr><tr><td>Channels</td><td>Telegram, Feishu, AIHUB, etc. — see <a href="/aibutler/docs-versions/v1.1.2/en/guide/channels.html">Channels</a></td></tr><tr><td>Advanced</td><td>Less common settings</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Just tell it, instead of editing the profile</p><p>&quot;Keep your replies shorter from now on,&quot; &quot;just call me Wang,&quot; &quot;give me the conclusion first&quot; — say these to it directly and it will remember on its own. That&#39;s easier than editing the profile.</p></div><h2 id="how-its-memory-works" tabindex="-1">How its memory works <a class="header-anchor" href="#how-its-memory-works" aria-label="Permalink to &quot;How its memory works&quot;">​</a></h2><p>Each persona has a long-term memory store, kept on your own computer.</p><ul><li><strong>It remembers what you tell it</strong>: your habits, decisions you&#39;ve made, rules you&#39;ve set, places where you&#39;ve corrected it.</li><li><strong>It checks its memory before acting</strong>: so once you&#39;ve taught it something, you don&#39;t need to teach it again.</li><li><strong>When you correct it, it updates</strong>: if it remembers something wrong or does something wrong, just say &quot;no, it should be…&quot; and it will overwrite the old memory.</li></ul><p>When a conversation runs too long, the persona tidies up on its own: it saves what matters to memory and a handoff note, then clears its context and starts fresh. So after reopening, it may not remember the exact words of the chat, but it remembers what matters. To make sure something sticks, just say &quot;Remember: …&quot;.</p><h2 id="export-and-import" tabindex="-1">Export and import <a class="header-anchor" href="#export-and-import" aria-label="Permalink to &quot;Export and import&quot;">​</a></h2><ul><li><strong>Export</strong>: in the Personas window, click <strong>⋯</strong> on a persona&#39;s card → <strong>Export</strong>. The whole persona becomes a single file, memory and identity included.</li><li><strong>Import</strong>: click <strong>Import from file…</strong> at the bottom of the Personas window and pick that file. After importing, it&#39;s still itself — the memory comes along too.</li></ul><p>The exported file does <strong>not</strong> include: any kind of key or token (re-enter these after importing), raw chat history, or attachments. So sharing it with a friend won&#39;t leak your credentials.</p><p>Uses: moving to a new computer, sharing a persona you&#39;ve trained up with a friend, backups.</p><h2 id="personas-can-help-each-other" tabindex="-1">Personas can help each other <a class="header-anchor" href="#personas-can-help-each-other" aria-label="Permalink to &quot;Personas can help each other&quot;">​</a></h2><p>Personas on the same computer can consult each other — for example, have &quot;Researcher&quot; look something up and hand it to &quot;Writer&quot; to put together. Once connected to <a href="/aibutler/docs-versions/v1.1.2/en/guide/aihub.html">AIHUB</a>, they can also exchange messages with personas on other people&#39;s computers.</p><p>Just tell your persona directly:</p><blockquote><p>Ask Researcher whether they found that market data from last week yet.</p></blockquote><h2 id="hand-work-off-to-the-background" tabindex="-1">Hand work off to the background <a class="header-anchor" href="#hand-work-off-to-the-background" aria-label="Permalink to &quot;Hand work off to the background&quot;">​</a></h2><p>For big or slow jobs, a persona can send one or several helpers to look things up or run commands in the background while it keeps talking with you; it reports back when they finish. Running jobs are listed in the task panel. Helpers use a cheaper model from the same provider as the main model by default.</p><p>You don&#39;t have to ask — it splits work off when it makes sense. You can also say it directly:</p><blockquote><p>Send a few helpers to look into these three companies in parallel, then give me a summary.</p></blockquote>',29)])])}const g=t(s,[["render",i]]);export{m as __pageData,g as default};
